CREATE PROCEDURE bud.usp_Cleanup_Obsolete_Budget_DocEntries1  AS  BEGIN      SET NOCOUNT ON;           -- Step 0: Drop temp table if exists      IF OBJECT_ID('tempdb..#ValidDocEntries') IS NOT NULL          DROP TABLE #ValidDocEntries;           -- Step 1: Create temp table      CREATE TABLE #ValidDocEntries (          DocEntry INT PRIMARY KEY      );           -- Step 2: Try to get data from TEST_OIL_11FEB DRAFT_APPROVAL procedure      BEGIN TRY          -- Create temp table for procedure results with all the columns it returns          CREATE TABLE #ProcResults (              Branch NVARCHAR(50),              DocEntry INT,              ObjectName NVARCHAR(100),              ObjType INT,              LineNum INT,              VisOrder INT,              AcctCode NVARCHAR(50),              AcctName NVARCHAR(255),              CardCode NVARCHAR(50),              CardName NVARCHAR(255),              EFFECTMONTH NVARCHAR(50),              BUDGET NVARCHAR(100),              SUB_BUDGET NVARCHAR(100),              STATE NVARCHAR(50),              DocDate DATETIME,              CreateDate DATETIME,              AMOUNT DECIMAL(18,6),              CURRENTMONTH NVARCHAR(50),              Current_month_Posted_Amount DECIMAL(18,6),              Budget_Owner NVARCHAR(255),              OwnerCode NVARCHAR(50),              [Approver Name] NVARCHAR(255),              ApprovalCode NVARCHAR(50),              Current_month_Budget DECIMAL(18,6),              Status NVARCHAR(10),              U_NAME NVARCHAR(255),              CreatedDate DATETIME,              CreateTime INT,              LineRemarks NVARCHAR(MAX),              Comments NVARCHAR(MAX),              ProcesStat NVARCHAR(10),              UpdateDate DATETIME,              OcrCode NVARCHAR(50),              ACOMMENT NVARCHAR(MAX),              VCOMMENT NVARCHAR(MAX),              VerifiedStatus NVARCHAR(50),              ApprovedStatus NVARCHAR(50)          );                   -- Execute procedure and capture results          INSERT INTO #ProcResults          EXEC ('CALL "JIVO_OIL_HANADB"."DRAFT_APPROVAL"') AT HANA112;                   -- Insert only non-null, distinct DocEntry values into main temp table          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT DocEntry          FROM #ProcResults          WHERE DocEntry IS NOT NULL            AND NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = #ProcResults.DocEntry);                   DROP TABLE #ProcResults;                   PRINT 'Successfully retrieved data from TEST_OIL_11FEB.DRAFT_APPROVAL procedure.';      END TRY      BEGIN CATCH          -- Clean up temp table if it exists          IF OBJECT_ID('tempdb..#ProcResults') IS NOT NULL              DROP TABLE #ProcResults;                       PRINT 'Could not retrieve data from TEST_OIL_11FEB.DRAFT_APPROVAL procedure: ' + ERROR_MESSAGE();          PRINT 'Continuing with other data sources...';      END CATCH           -- Step 2a: Insert DocEntries from TEST_OIL_11FEB OJDT where ObjType = 28      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_OIL_HANADB"."OJDT" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_OIL_11FEB.OJDT table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_OIL_11FEB.OJDT: ' + ERROR_MESSAGE();      END CATCH           -- Step 2b: Insert DocEntries from TEST_BEV_11FEB OJDT where ObjType = 28      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_BEVERAGES_HANADB"."OJDT" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_BEV_11FEB.OJDT table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_BEV_11FEB.OJDT: ' + ERROR_MESSAGE();      END CATCH           -- Step 2c: Insert DocEntries from TEST_OIL_11FEB JDT1      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_OIL_HANADB"."JDT1" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_OIL_11FEB.JDT1 table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_OIL_11FEB.JDT1: ' + ERROR_MESSAGE();      END CATCH           -- Step 2d: Insert DocEntries from TEST_BEV_11FEB JDT1      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_BEVERAGES_HANADB"."JDT1" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_BEV_11FEB.JDT1 table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_BEV_11FEB.JDT1: ' + ERROR_MESSAGE();      END CATCH           -- Step 2e: Insert DocEntries from TEST_OIL_11FEB OBTF      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_OIL_HANADB"."OBTF" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_OIL_11FEB.OBTF table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_OIL_11FEB.OBTF: ' + ERROR_MESSAGE();      END CATCH           -- Step 2f: Insert DocEntries from TEST_BEV_11FEB OBTF      BEGIN TRY          INSERT INTO #ValidDocEntries (DocEntry)          SELECT DISTINCT "BatchNum"          FROM OPENQUERY(HANA112, 'SELECT "BatchNum" FROM "JIVO_BEVERAGES_HANADB"."OBTF" WHERE "ObjType" = 28 AND "BatchNum" IS NOT NULL')          WHERE NOT EXISTS (SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = "BatchNum");                   PRINT 'Successfully retrieved data from TEST_BEV_11FEB.OBTF table.';      END TRY      BEGIN CATCH          PRINT 'Error retrieving data from TEST_BEV_11FEB.OBTF: ' + ERROR_MESSAGE();      END CATCH           -- Display count of valid entries found      DECLARE @ValidCount INT;      SELECT @ValidCount = COUNT(*) FROM #ValidDocEntries;      PRINT 'Total valid DocEntries found from both schemas: ' + CAST(@ValidCount AS VARCHAR(10));           -- Step 3: Delete obsolete entries from jsBudgetTable      BEGIN TRY          DECLARE @DeletedBudget INT;                   DELETE FROM bud.jsBudgetTable          WHERE ObjType = 28            AND NOT EXISTS (                SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = jsBudgetTable.DocEntry            );                     SET @DeletedBudget = @@ROWCOUNT;          PRINT 'Deleted ' + CAST(@DeletedBudget AS VARCHAR(10)) + ' obsolete entries from jsBudgetTable.';      END TRY      BEGIN CATCH          PRINT 'Error deleting from jsBudgetTable: ' + ERROR_MESSAGE();      END CATCH           -- Step 4: Delete obsolete entries from jsDocEntry      BEGIN TRY          DECLARE @ObsoleteDocEntryCount INT;                   SELECT @ObsoleteDocEntryCount = COUNT(*)          FROM bud.jsDocEntry          WHERE NOT EXISTS (              SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = jsDocEntry.DocEntry          );                   PRINT 'Found ' + CAST(@ObsoleteDocEntryCount AS VARCHAR(10)) + ' obsolete entries in jsDocEntry that would be deleted.';                   -- Show the actual records that would be deleted          SELECT *          FROM bud.jsDocEntry          WHERE NOT EXISTS (              SELECT 1 FROM #ValidDocEntries v WHERE v.DocEntry = jsDocEntry.DocEntry          );               END TRY      BEGIN CATCH          PRINT 'Error selecting from jsDocEntry: ' + ERROR_MESSAGE();      END CATCH           -- Step 5: Drop temp table      IF OBJECT_ID('tempdb..#ValidDocEntries') IS NOT NULL          DROP TABLE #ValidDocEntries;           PRINT 'Cleanup check procedure completed successfully.';  END;
